/*
 * Function: Polarity
 * --------------------
 * Sets MUX36D08 switch polarity.
 */
void
Polarity (uint8_t polar)
{
  switch (polar)
    {
    case 1: // Forward polarity
      MUX36D08_output (0x01);
      break;
    case 2: // Reversed polarity
      MUX36D08_output (0x02);
      break;
    case 0: // Shunted
      MUX36D08_output (0x00);
      break;
    }
}

/*
 * Function: Pulse_On
 * --------------------
 * Activates current reference at P0.7.
 * Reads amplitude bit from SMBus as Iset.
 */
void
Pulse_On (void)
{
  IREF0CN0 = IREF0CN0_SINK__DISABLED | IREF0CN0_MDSEL__HIGH_CURRENT
      | (Iset << IREF0CN0_IREF0DAT__SHIFT);
}

/*
 * Function: Pulse_Off
 * --------------------
 * Deactivates current reference at P0.7.
 * Reads amplitude bit from SMBus as Iset.
 */
void
Pulse_Off (void)
{
  IREF0CN0 = IREF0CN0_SINK__DISABLED | IREF0CN0_MDSEL__HIGH_CURRENT
      | (0x00 << IREF0CN0_IREF0DAT__SHIFT); // Current 0 mA
}

/* Function: T0_Waitus
 * --------------------
 * Wait function based on timer 0 overflow.
 * Overflows every 50 us. Does not generate interrupt.
 * Commented lines are original overflow bits and some of my calculations.
 */
void
T0_Waitus (uint16_t us)
{
  TCON &= ~0x30;                      // Stop Timer0; Clear TCON_TF0
  TMOD &= ~0x0f;                      // 16-bit free run mode
  TMOD |= 0x01;

  //CKCON0 |= 0x04;                      // Timer0 counts SYSCLKs
  //CKCON0 |= 0x00; // Timer 0 uses prescale SCA clock
  CKCON0 |= 0x01; // Timer 0 prescale value System Clock / 4

  while (us)
    {
      TCON_TR0 = 0;                         // Stop Timer0
      TH0 = (0xFD << TH0_TH0__SHIFT); //
      TL0 = (0x9B << TL0_TL0__SHIFT); //
      TCON_TF0 = 0;                         // Clear overflow indicator
      TCON_TR0 = 1;                         // Start Timer0
      while (!TCON_TF0)
        ;                    // Wait for overflow
      us--;                            // Update us counter
    }
  TCON_TR0 = 0;                            // Stop Timer0
}

void
T2_Set(uint16_t T) {
  // $[Timer Initialization]
    // Save Timer Configuration
    uint8_t TMR2CN0_TR2_save;
    TMR2CN0_TR2_save = TMR2CN0 & TMR2CN0_TR2__BMASK;
    // Stop Timer
    TMR2CN0 &= ~(TMR2CN0_TR2__BMASK);
    // [Timer Initialization]$

    // $[TMR2CN0 - Timer 2 Control]
    // [TMR2CN0 - Timer 2 Control]$

    // $[TMR2H - Timer 2 High Byte]
    // [TMR2H - Timer 2 High Byte]$

    // $[TMR2L - Timer 2 Low Byte]
    // [TMR2L - Timer 2 Low Byte]$

    // $[TMR2RLH - Timer 2 Reload High Byte]
    /***********************************************************************
     - Timer 2 Reload High Byte = 0x38
     ***********************************************************************/
    TMR2RLH = ( (T >> 8) << TMR2RLH_TMR2RLH__SHIFT);
    // [TMR2RLH - Timer 2 Reload High Byte]$

    // $[TMR2RLL - Timer 2 Reload Low Byte]
    /***********************************************************************
     - Timer 2 Reload Low Byte = 0x9E
     ***********************************************************************/
    TMR2RLL = ( (T & 0xFF) << TMR2RLL_TMR2RLL__SHIFT);
    // [TMR2RLL - Timer 2 Reload Low Byte]$

    // $[TMR2CN0]
    // [TMR2CN0]$

    // $[Timer Restoration]
    // Restore Timer Configuration
    TMR2CN0 |= TMR2CN0_TR2_save;
    // [Timer Restoration]$
}

void
WriteStimOffToNFC (void)
{
  if (!StimOffNFCSentFlag) {
      StimOffNFCSentFlag = 1;
      // 1. Process and write the sampled voltage for the channel that just stimulated
      Write_mV(ADCBuf, sample_cnt, channel_nr | 0x80);
      sample_cnt = 0; // Reset the sample count buffer for the next channel stim
      // 2. Tell the transmitter the device is now resting
//      Write_Channel(channel_nr | 0x80); // high bit = stim off, lower 7 = channel
  }
}

/* Function: SMB_Write
 * --------------------
 * Creates interrupt for the SMBus to initiate a writing sequence
 * of the SMB_DATA_OUT array. The SMBus clock is based on the Timer 1 overflow.
 */
void
SMB_Write (void)
{
  while (SMB_BUSY)
    ;                   // Wait for SMBus to be free.
  SMB_BUSY = 1;                       // Claim SMBus (set to busy)
  SMB_RW = 0;                         // Mark this transfer as a WRITE
  SMB0CN0_STA = 1;                            // Start transfer

  while (SMB_BUSY)
    ;
}

/* Function: SMB_Read
 * --------------------
 * Creates interrupt for the SMBus to initiate a reading sequence
 * and returns the read data in the SMB_DATA_OUT array.
 * The SMBus clock is based on the Timer 1 overflow.
 */
void
SMB_Read (void)
{
  while (SMB_BUSY)
    ;               // Wait for bus to be free.
  SMB_BUSY = 1;                       // Claim SMBus (set to busy)
  SMB_RW = 1;                         // Mark this transfer as a READ
  SMB0CN0_STA = 1;                            // Start transfer

  while (SMB_BUSY)
    ;               // Wait for transfer to complete
}

void ReadAndApplyNFCParameters(void) {
  // 1. Start Timer 1 for SMBus clock (TR1 is bit 6)
  TCON |= 0x40;
  // 2. Read the first 16 bytes from NFC memory
  TARGET = SLAVE_ADDR;
  SMB_Read();
  // 3. Stop Timer 1 to save energy
//  TCON &= ~0x40;
  // 4. Update all global parameters directly from the read buffer
  PW_HB = SMB_DATA_IN[0];
  PW_LB = SMB_DATA_IN[1];
  T_HB = SMB_DATA_IN[2];
  T_LB = SMB_DATA_IN[3];
  T_on_HB = SMB_DATA_IN[4];
  T_on_LB = SMB_DATA_IN[5];
  On = SMB_DATA_IN[6];
  Iset = SMB_DATA_IN[7];
  mode = SMB_DATA_IN[8];
  channel_nr = SMB_DATA_IN[9];
  telemetry_enabled = SMB_DATA_IN[10];
  // 5. Reconstruct 16-bit parameters
  PW = (PW_HB << 8) | (PW_LB);
  T = (T_HB << 8) | (T_LB);
  T_on = (T_on_HB << 8) | (T_on_LB);
  T_on_double = 2 * T_on;
  // 6. Transition state based on the 'On' byte
  P05 = On;
  if (On) {
    T2_Set(T); // Apply the new frequency timer
    if (mode == 1) current_state = STATE_RUN_SINGLE;
    else if (mode == 2) current_state = STATE_RUN_SWEEP_ONCE;
    else if (mode == 3) current_state = STATE_RUN_SWEEP_LOOP;
  } else {
    current_state = STATE_IDLE;
  }
}

/*
 * Function: MUX36S16_output
 * -------------------------------
 * MUX36D08 output selection function
 * Selects output channel of the stimulation.
 *
 * mux36s16_state:switch state read from NT3H.
 * Switch state converted to corresponding bits that are set as control pins for MUX36
 * as per MUX36 truth table.
 * MUX36S16 truth table:
 * EN A3 A2 A1 A0 ON-CHANNEL
 * 0  X  X  X  X  All channels are off
 * 1 0 0 0 0 Channel 1
 * 1 0 0 0 1 Channel 2
 * 1 0 0 1 0 Channel 3
 * 1 0 0 1 1 Channel 4
 * 1 0 1 0 0 Channel 5
 * 1 0 1 0 1 Channel 6
 * 1 0 1 1 0 Channel 7
 * 1 0 1 1 1 Channel 8
 * 1 1 0 0 0 Channel 9
 * 1 1 0 0 1 Channel 10
 * 1 1 0 1 0 Channel 11
 * 1 1 0 1 1 Channel 12
 * 1 1 1 0 0 Channel 13
 * 1 1 1 0 1 Channel 14
 * 1 1 1 1 0 Channel 15
 * 1 1 1 1 1 Channel 16
 */
void
MUX36S16_output (uint8_t mux36s16_state)
{
  /*
   * Because channel 14 for the output MUX36S16 is skipped,
   * channel numbers are shifted by one for the channel 14 (decimal code 13, hex D) and 15
   * (decimal code 14, hex E). Calibrate that such that user can input standard channels
   * according to the channel cuff enumeration.
   */

  if (mux36s16_state >= 13)
    {
      mux36s16_state = mux36s16_state + 1;
    }
  P17 = (mux36s16_state & (1 << (1 - 1))) ? 1 : 0; // Get 1st bit of MUX36S16 state byte
  P16 = (mux36s16_state & (1 << (2 - 1))) ? 1 : 0; // Get 2nd bit of the state byte
  P15 = (mux36s16_state & (1 << (3 - 1))) ? 1 : 0; // Get 3rd bit of the state byte
  P14 = (mux36s16_state & (1 << (4 - 1))) ? 1 : 0; // Get 4th bit of the state byte
}

/*
 * Function: MUX36D08_output
 * -------------------------------
 * MUX36D08 output selection function
 * Selects output channel of the stimulation.
 *
 * mux36d08_state:switch state read from NT3H.
 * Switch state converted to corresponding bits that are set as control pins for MUX36
 * as per MUX36 truth table.
 * MUX36D08 truth table:
 * EN A2  A1  A0  ON-CHANNEL
 * 0  X   X   X   All channels are off
 * 1  0   0   0   Channels 1A and 1B
 * 1  0   0   1   Channels 2A and 2B
 * 1  0   1   0   Channels 3A and 3B
 * 1  0   1   1   Channels 4A and 4B
 * 1  1   0   0   Channels 5A and 5B
 * 1  1   0   1   Channels 6A and 6B
 * 1  1   1   0   Channels 7A and 7B
 * 1  1   1   1   Channels 8A and 8B
 */
void
MUX36D08_output (uint8_t mux36d08_state)
{
  P02 = (mux36d08_state & (1 << (1 - 1))) ? 1 : 0; // Get 1st bit of MUX36D08 state byte
  P03 = (mux36d08_state & (1 << (2 - 1))) ? 1 : 0; // Get 2nd bit of the state byte
  P04 = (mux36d08_state & (1 << (3 - 1))) ? 1 : 0; // Get 3rd bit of the state byte
}

/*
 * Function: Write_Channel
 * -----------------------
 * For the multichannel stimulation writes the current channel number to NT3H
 * (Address 8 on the NFC Tools GUI)
 */
void
Write_Channel (uint8_t channel_to_write) // write channel
{

  TCON |= TCON_TR1__RUN; // start timer 1 for SMBus clock
  SMB_DATA_OUT[0] = channel_to_write;
  TARGET = SLAVE_ADDR;
  SMB_Write ();                     // Initiate SMBus write
//  TCON &= ~TCON_TR1__BMASK; // stop the timer 1 to save energy
}

void Write_mV(uint16_t *buffer, uint8_t length, uint8_t channel_to_write) {
    uint8_t mV_LB;
    uint8_t mV_HB;
    uint8_t i; // iterator for the ADCBuf
    uint16_t mV_mean = 0;
    SMB_DATA_OUT[0] = channel_to_write;

    if (length == 0) {
        TCON |= TCON_TR1__RUN;    // Start Timer 1 for SMBus clock
        SMB_DATA_OUT[1] = 0;
        SMB_DATA_OUT[2] = 0;
        TARGET = SLAVE_ADDR;
        SMB_Write ();
//        TCON &= ~TCON_TR1__BMASK; // stop the timer 1 to save energy
        return;
    }

    // Stop ADC interrupts:
    EIE1 &= ~(EIE1_EADC0__BMASK); // disable ADC interrupt - AND with the inverse ADC interrupts mask
    // Accumulate sampled ADC values:
    for (i = 0; i < length; i++) {
        mV_mean = mV_mean + buffer[i];
    }
    mV_mean = mV_mean / length; // don't care about the decimal of floating precision - just an estimate of voltage on the interface

    // Re-enable ADC interrupts:
    EIE1 |= EIE1_EADC0__BMASK; // endable ADC interrupt - OR with the ADC interrupts mask

    mV_LB = mV_mean & 0xFF; // get the low byte
    mV_HB = mV_mean >> 8; // get the high byte
    // SMB_DATA_OUT[0] is reserved for the stimulation channel number
    TCON |= TCON_TR1__RUN;    // Start Timer 1 for SMBus clock
    SMB_DATA_OUT[1] = mV_LB;
    SMB_DATA_OUT[2] = mV_HB;
    TARGET = SLAVE_ADDR;
    SMB_Write ();                     // Initiate SMBus write
//    TCON &= ~TCON_TR1__BMASK; // stop the timer 1 to save energy
}
